import{_ as t}from"./chunks/19e9c12ccbd9b8720c8d.CIRwMA24.js";import{_ as o,o as a,c as i,a6 as n}from"./chunks/framework.CnPv4DE1.js";const f=JSON.parse('{"title":"Life Is Hard, Get Used To It (The Way To Mental Mastery)","description":"","frontmatter":{"title":"Life Is Hard, Get Used To It (The Way To Mental Mastery)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md","filePath":"en/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md"}'),s={name:"en/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery.md"};function r(h,e,l,p,u,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="life-is-hard-get-used-to-it-the-way-to-mental-mastery" tabindex="-1">Life Is Hard, Get Used To It (The Way To Mental Mastery) <a class="header-anchor" href="#life-is-hard-get-used-to-it-the-way-to-mental-mastery" aria-label="Permalink to &quot;Life Is Hard, Get Used To It (The Way To Mental Mastery)&quot;">​</a></h1><p>Dan Koe · 2023-02-25 · <a href="https://thedankoe.com/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/life-is-hard-get-used-to-it-the-way-to-mental-mastery">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/aMZv0uoHMPI?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em>Comfort is an impermanent state of mind that humans love to call home.</em></p><p>What’s funny is that the longer we box ourselves into this mental house we refuse to leave, the more uncomfortable it gets.</p><p>The only path to true comfort is by <em>reaching the level of mind that is comfortable with the inevitable discomfort that life presents</em>_._</p><p><strong>The problem is this:</strong></p><p>When people are faced with discomfort, their automatic reaction is to flee, not fight.</p><p>We may not flee from the physical situation, but we attempt to run toward the mental comfort of a past experience. Our mind wants to move even when we are still.</p><p>This creates tension, and unless that tension is resolved it stays around longer than it should.</p><p><em>The result of this problem is distraction, feeling “lost,” and getting stuck in a rut.</em></p><p>We don’t know what to pursue next, because we lack the clarity that discomfort provides with time.</p><p>When we are in this “lost” or chaotic state of mind, it’s impossible to see beyond the initial problem.</p><p>Why? Because it’s begging to be solved.</p><p>The mind determines how we interact with reality.</p><p>The mind houses perspective houses perception houses behavior.</p><p>From the top down, most people hold a narrow perspective that leads to a negative perception of a situation which dictates their mindless behavior.</p><p>The goal is to move through life with artfulness and grace.</p><p>That is, to be at one with the present moment regardless of how the mind wants to interpret the difficulty of the situation.</p><p>When you:</p><ul><li>Broaden your perspective by approaching life with an open mind</li><li>Gain the power to accept situations as they are</li><li>Reap the joy that comes from progress</li></ul><p>You come to the realization that you’ve been sold a lie.</p><p>The conventional path is not the path to the good life.</p><p>To do this well, there are a few things you need to understand.</p><h2 id="the-3-perspectives" tabindex="-1">The 3 Perspectives <a class="header-anchor" href="#the-3-perspectives" aria-label="Permalink to &quot;The 3 Perspectives&quot;">​</a></h2><p>The space between expectation and reality creates tension that causes pain.</p><p>I love philosophy, but realized fast that theory has to meet practice.</p><p>Knowledge must be brushed up against reality, in more ways than one, to determine its validity.</p><p>A philosopher can intellectualize all day, but can they run a business?</p><p>How do they react when they lose $100,000?</p><p>What about when you <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">start writing content</a>, gain a follower, but lose 5 more?</p><p>Can they create, keep, and nurture a relationship?</p><p>Or are they just guessing about how to create a good one and promoting it as “the best path” to those that learn from them?</p><p>What about when their dog dies? How about their parents?</p><p>Actions must align with words.</p><p>An overweight health expert is a clear example of someone that is difficult to trust, but anyone can hide behind an anonymous online profile.</p><p>The best philosophy is that which is grounded in reality, and that is individual.</p><p>I want to give 3 perspectives to help you realize the importance of reducing the space between expectation and reality, concept and experience, and what is and what isn’t.</p><h3 id="expectation-vs-reality" tabindex="-1">Expectation VS Reality <a class="header-anchor" href="#expectation-vs-reality" aria-label="Permalink to &quot;Expectation VS Reality&quot;">​</a></h3><p>Expectations are beliefs, and our beliefs are often unconscious and conditioned into our mind as we go about life.</p><p>An expectation is a projection into the future.</p><p>It is the assumption that something “should” or “will” happen.</p><p>Western children are often told they “should” become a doctor, engineer, or some other high-paying job title.</p><p>Kids are told they “will” go to Church on Sunday, and they believe it.</p><p>Expectations narrow your mind toward a predictable future and prevent us from opening your mind to potential futures.</p><p>From this narrow-minded state, our perspective is limited.</p><p>Since our perspective is limited, so is our perception of the situation.</p><p>With an inaccurate perception, we often make choices that are inconducive to our ideal future.</p><p>And choices are important, they create your future one brick at a time.</p><p>Let’s look at the example of hot weather and a sauna.</p><p>When people think about going out in hot weather, they complain, because their expectation narrows their mind on a negative outcome.</p><p>When people think about going to the sauna, it is intentional. Usually in alignment with a meaningful outcome.</p><p>The reality of the situation is the same, but the expectation is different, and that causes pain in the former situation.</p><p>In a more practical situation, let’s look at someone with a lot of responsibility that wants to start a business.</p><ul><li>They see others with little responsibility flexing their business success within 6-12 months.</li><li>They hold that expectation in your mind without context for their situation.</li><li>They conceptualize why they can’t do the same and how life is unfair (because they have a job, kids, and a spouse).</li></ul><p>They fail to face reality.</p><p>And the reality is that they did not hop on the opportunity to build a business when they had less responsibilities, and that’s fine. There’s no changing it, and the sooner you accept reality for what it is, the sooner you’ll be able to start making progress.</p><p>Because once they do accept reality, they can approach that goal from a new lens, a more sustainable one.</p><p>They can search for aligned mentors, education, and strategies that will result in the same success, but on a longer time scale.</p><p>The only other option is to become a slave to your expectations and never reach that goal, going about life knowing it’s possible, but complaining that you aren’t able to achieve the same thing.</p><h3 id="concept-vs-experience" tabindex="-1">Concept VS Experience <a class="header-anchor" href="#concept-vs-experience" aria-label="Permalink to &quot;Concept VS Experience&quot;">​</a></h3><p>Concepts can only be created from experience.</p><p>The prime example of this misunderstanding is that of God, The Universe, or whatever you want to call the higher power.</p><p>Religious people attach to the concept of God but fail to realize that it is an experience. The concept is simply a symbolic representation of that experience.</p><p>The difference is knowing and understanding.</p><p>Concepts allow you to know, experience allows you to understand.</p><p>Knowledge is a layer on top of reality, understanding is an inherent aspect of human consciousness.</p><p>One an outward construction, the other an inward truth.</p><p>Concept is the guide that must brush up against reality to be experienced.</p><p>Reality is experience, and that’s all there is, if you’re paying attention.</p><p>People love to conceptualize because they can do so without moving forward in the world to solve problems (internal and external) that result in a less superficial and reactively emotional experience.</p><h3 id="what-is-vs-what-isn-t" tabindex="-1">What Is VS What Isn’t <a class="header-anchor" href="#what-is-vs-what-isn-t" aria-label="Permalink to &quot;What Is VS What Isn’t&quot;">​</a></h3><p>“It is what it is” is the most profound statement you will hear in your life, but few people realize the depth behind it.</p><p>Making a distinction between “what is” and “what isn’t” is a great way to close the space between expectations and reality, as well as concept and experience.</p><p>The present moment, what’s right in front of you, is “what is.”</p><p>The difficulty of the barbell in your hand is reality. The expectation that it should be easy is not.</p><p>The struggle of building a name for yourself is the experience. The concept of a fulfilling lifestyle in your mind isn’t.</p><p>And if you want to start this journey toward long-term success, enroll in the <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics masterclass.</a></p><p>Now, I’m not saying that expectations, concepts, and “what isn’t” are bad.</p><p>The main problem are the negative expectations, the concepts that “know” and prevent you from action, and an inability to be at one with “what is.”</p><h3 id="the-point" tabindex="-1">The Point <a class="header-anchor" href="#the-point" aria-label="Permalink to &quot;The Point&quot;">​</a></h3><p>With all of these perspectives, the point is this:</p><p>When life is difficult, overwhelming, or you feel that dreaded sense of despair about your future, there is a dissonance between expectation and reality.</p><p>The beliefs, ideas, or thoughts in your head do not match the present moment that is unfolding in front of you.</p><p>And because you give them too much attention, they take priority over and mask your sensory perceptions.</p><p>In another word, you can clean your room, and you can clean it well, even if you don’t <em>feel</em> like cleaning it.</p><p>Feel free to exchange “clean your room” with any given activity.</p><h2 id="levels-of-mind" tabindex="-1">Levels Of Mind <a class="header-anchor" href="#levels-of-mind" aria-label="Permalink to &quot;Levels Of Mind&quot;">​</a></h2><blockquote><p>No problem can be solved from the same level of consciousness that created it. – Albert Einstein</p></blockquote><p>Problems are encoded in the system and few people can see them for what they are.</p><p>Problems are what spark the gap between expectation and reality, and only once you can close that gap does that problem become effortless to solve.</p><p>But, in order to solve that problem and close that gap, you must reach a new level of mind.</p><p>We will define “mind” as how you interact with reality.</p><p>Mind, in this sense, is perspective.</p><p>Think of perspective as a field that holds all expectations, beliefs, ideas, skills, experience, potentialities, and the rest.</p><p>The broader this perspective becomes, the more you increase your level of mind, and the more difficult it is to latch on to one expectation, belief, skill, etc.</p><p>With each problem you solve, the perceived difficulty of life goes down, and your level of mind goes up.</p><p>The degree of problems you face is a prime indicator of the stage of personal development you are in.</p><p>And the degree of problems you can solve is the degree of problems you can solve for another.</p><p>Meaning, the more you develop yourself, by taking on an ever-increasing level of challenge, the more experience you gain.</p><p>The challenges you face will you require to close the gap between expectation and reality many times, and each time you do, you will be presented with a lesson.</p><p>This experience can be transferred into business, as products solve problems, so the higher your experience, the more profitable your business becomes.</p><p>There must be a balance, as you would not try to climb Mount Everest when you can’t even sustain a habit of 10K steps a day.</p><h2 id="live-at-your-edge-–-the-way-to-mental-mastery" tabindex="-1">Live At Your Edge – The Way To Mental Mastery <a class="header-anchor" href="#live-at-your-edge-–-the-way-to-mental-mastery" aria-label="Permalink to &quot;Live At Your Edge – The Way To Mental Mastery&quot;">​</a></h2><blockquote><p>As you open yourself to living at your edge, your deepest purpose will slowly begin to make itself known. In the meantime, you will experience layer after layer of purposes, each one getting closer and closer to the fullness of your deepest purpose. – David Deida</p></blockquote><p>To reach new levels of mind, you have to encounter problems.</p><p>You can’t sit around, wasting away, doing the same thing over and over without regard for personal evolution.</p><p>You must live at the edge of skill and challenge.</p><p>As you solve problems, you increase your level of mind.</p><p>In order to solve problems, you must increase your level of skill.</p><h3 id="_1-pursue-a-challenging-goal" tabindex="-1">1) Pursue A Challenging Goal <a class="header-anchor" href="#_1-pursue-a-challenging-goal" aria-label="Permalink to &quot;1) Pursue A Challenging Goal&quot;">​</a></h3><p>This is a lesson in almost every single one of my newsletters.</p><p>You need a goal that you are working towards <em>every. single. day.</em></p><p>One that will lead to your ideal future, even if you don’t know what that future is.</p><p>I can assume that it involves a healthy body, abundant bank account, and thriving relationships (with peace of mind being the byproduct of pursuing those goals, not necessarily achieving them).</p><p>This goal will be achieved, and you will have to set a new one (that may not be clear for a while) in order to prevent and dig yourself out of subsequent ruts.</p><h3 id="_2-remain-conscious-of-the-present-moment-difficulty" tabindex="-1">2) Remain Conscious Of The Present Moment Difficulty <a class="header-anchor" href="#_2-remain-conscious-of-the-present-moment-difficulty" aria-label="Permalink to &quot;2) Remain Conscious Of The Present Moment Difficulty&quot;">​</a></h3><p>What judgments, connotations, and words do you associate with the words “struggle,” “difficulty,” or “hard?”</p><p>Do they lead to compulsive thoughts about a stressful future?</p><p>Maybe they lead to a memory of a past mistake… one that causes fear to the point of inaction?</p><p>Or maybe a mixture of both, leaving you in a vortex of anxiety?</p><p>Again, these are but expectations, concepts, and “what isn’ts” that you hold in your mind.</p><p>They are not reality, and reality includes struggle, difficulty, and hardness. You can’t escape them. And this requires radical acceptance of the present moment.</p><h3 id="_3-hit-the-critical-point-of-the-perception-threshold" tabindex="-1">3) Hit The Critical Point Of The Perception Threshold <a class="header-anchor" href="#_3-hit-the-critical-point-of-the-perception-threshold" aria-label="Permalink to &quot;3) Hit The Critical Point Of The Perception Threshold&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>If you have writer’s block…</p><p>If you’re 30 minutes into a 5k run…</p><p>If you’re on your last rep of a 365lb squat…</p><p>If you’re hesitant to post your first piece of content…</p><p>If you’re 45 minutes into a meditation session and your mind is begging you to check your notifications…</p><p>Thoughts and emotions will flood your mind, and “the only way out is through.”</p><p>You must <em>train</em> your pain tolerance because the magic happens when you stick it out for just enough time to hit “the runner’s high” in any situation.</p><p><strong>The Perception Threshold</strong> is the critical point after a period of struggle where <em>what was once difficult becomes effortless due to a shift in how you perceive the situation.</em></p><p><em>Expectations collapse into reality.</em></p><p><em>Concepts collapse into experience.</em></p><p><em>What isn’t collapses into what is.</em></p><p>This may take 5 minutes, it may take 1 hour, and with problems that aren’t immediately solvable, it may take years.</p><p>Chaos is a prerequisite to clarity, and clarity is the most potent fuel in this world.</p><h3 id="_4-reach-a-new-level-of-mind" tabindex="-1">4) Reach A New Level Of Mind <a class="header-anchor" href="#_4-reach-a-new-level-of-mind" aria-label="Permalink to &quot;4) Reach A New Level Of Mind&quot;">​</a></h3><p>Crossing The Perception Threshold forces you to zoom out to a higher level of mind, or more holistic perspective beyond the narrow state you were in.</p><p>From this level, you can accurately perceive your prior problem and see it for what it is.</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">“Not having ideas” for your writing becomes a silly excuse.</a></p><p>Not performing the last rep – that leads to the most gains – becomes “I’m being a little b*tch, push through.”</p><p>Not posting your first piece of content becomes, “If I don’t do this, it becomes habit, and I’ll be stuck in my current situation for life, which is the opposite of what I want.”</p><p>Deep satisfaction is the result.</p><p>– Dan</p><p><strong>What Happened This Week</strong></p><p>I’ve only got one thing for you.</p><p>Modern Mastery 2.0 has launched and is under contruction.</p><p>Less bloat, less overwhelm, more value, more personalized help.</p><p>Out of the 200+ articles and trainings, we will be adding more courses to be the education platform for the future of work.</p><p>YouTube courses, design, editing, visual composition, marketing, product building, and everything you’ll ever need.</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">If you’re interested, readers can join for $5 here.</a></p>',153)])])}const y=o(s,[["render",r]]);export{f as __pageData,y as default};
